import { NotFoundError } from "../domain/errors";
import { TaskRepository } from "../domain/task-repository";
import { UserRepository } from "../domain/user-repository";
import { AssignTaskInput, TaskDto, toTaskDto } from "./dtos";
import { TaskLookupService } from "./task-lookup-service";

export class AssignTaskUseCase {
  constructor(
    private readonly lookup: TaskLookupService,
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
  ) {}

  async execute(input: AssignTaskInput): Promise<TaskDto> {
    const task = await this.lookup.getInProject(input.projectId, input.taskId);
    const user = await this.users.findById(input.userId);
    if (!user) {
      throw new NotFoundError(`user ${input.userId} not found`);
    }
    task.assignTo(user.id);
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

